<script setup lang="ts">import{ref}from"vue";import{useRouter}from"vue-router";import BasePageHeader from"@/components/base/BasePageHeader.vue";import TitleForm from"@/features/catalog/components/TitleForm.vue";import type{TitleFormData}from"@/domain/catalog/models";import{mapTitleFormToPocketBase}from"@/domain/catalog/mapper";import{titleRepository}from"@/domain/repositories";const router=useRouter(),saving=ref(false),error=ref("");async function save(f:TitleFormData){saving.value=true;error.value="";try{const r=await titleRepository.create(mapTitleFormToPocketBase(f));await router.push({name:"catalog-detail",params:{id:r.id},query:{created:"1"}})}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{saving.value=false}}</script><template><BasePageHeader eyebrow="Catálogo" title="Adicionar título" description="Cria uma entrada com os lookups da base atual."/><div v-if="error" class="form-alert form-alert-error">{{error}}</div><TitleForm :saving="saving" @submit="save"/></template>
